import { useEffect, useRef, useState } from 'react'
import { Link, Navigate, Route, Routes, useLocation, useNavigate } from 'react-router-dom'
import { Activity as ActivityIcon, ArrowDownToLine, Bell, BookOpen, BriefcaseBusiness, ChartNoAxesCombined, CheckCircle2, ChevronRight, ClipboardList, FileText, GraduationCap, LayoutDashboard, LogOut, Menu, Plus, Search, ShieldCheck, UserRound, X } from 'lucide-react'
import api from './api'

const categories = [
  ['PUBLICATION','Research publication'],['BOOK','Book / Chapter'],['SEMINAR','Seminar / Conference'],['FDP','FDP / Workshop'],['PROJECT','Research / Academic project'],['TEACHING','Teaching activity'],['PATENT','Patent'],['AWARD','Award / Recognition'],['SERVICE','Institutional / Community service'],['OTHER','Other achievement']
]
const roleLabel = { FACULTY:'Faculty member', HOD:'HOD / Reviewer', ADMIN:'University administrator' }
const fmtDate = (v) => v ? new Date(v).toLocaleDateString('en-IN') : '—'
const moneyOrScore = (v) => Number(v || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 })
const evidenceUploadMaxMb = Number(import.meta.env.VITE_EVIDENCE_UPLOAD_MAX_MB || 10)
const apiErrorMessage = (error, fallback) => {
  const data = error.response?.data
  if (typeof data?.detail === 'string') return data.detail
  if (data && typeof data === 'object') {
    const messages = Object.entries(data).flatMap(([field, value]) =>
      (Array.isArray(value) ? value : [value]).map(message =>
        `${field}: ${typeof message === 'string' ? message : JSON.stringify(message)}`,
      ),
    )
    if (messages.length) return messages.join(' ')
  }
  return fallback
}

function Protected({ user, children }) { return user ? children : <Navigate to="/login" replace /> }
function App() {
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(true)
  const location = useLocation()
  const navigate = useNavigate()
  useEffect(() => {
    if (localStorage.getItem('access_token')) api.get('auth/me/').then(r => setUser(r.data)).catch(() => setUser(null)).finally(() => setLoading(false))
    else setLoading(false)
  }, [])
  const login = async (username, password) => {
    const { data } = await api.post('auth/token/', { username, password })
    localStorage.setItem('access_token', data.access); localStorage.setItem('refresh_token', data.refresh)
    const me = await api.get('auth/me/'); setUser(me.data); navigate('/')
  }
  const logout = () => { localStorage.clear(); setUser(null); navigate('/login') }
  if (loading) return <div className="loading-screen">Loading FacultyAdvance…</div>
  if (!user) return <Routes><Route path="/register" element={<Register />} /><Route path="/reset-password" element={<PasswordRecovery />} /><Route path="/verify-email" element={<VerifyEmailPage />} /><Route path="/resend-verification" element={<ResendVerificationPage />} /><Route path="/sso/callback" element={<GoogleSSOCallback onLogin={setUser} />} /><Route path="*" element={<Login onLogin={login} />} /></Routes>
  const isReviewer = user.role !== 'FACULTY'
  const links = user.role === 'FACULTY' ? [
    { to:'/', label:'Overview', icon:LayoutDashboard },
    { to:'/activities', label:'My activities', icon:BookOpen },
    { to:'/research', label:'Publication finder', icon:Search },
    { to:'/appraisal', label:'My appraisal', icon:ClipboardList },
    { to:'/notifications', label:'Notifications', icon:Bell },
  ] : user.role === 'ADMIN' ? [
    { to:'/', label:'Overview', icon:LayoutDashboard },
    { to:'/activities', label:'Department activities', icon:BookOpen },
    { to:'/reviews', label:'Appraisal reviews', icon:ShieldCheck },
    { to:'/notifications', label:'Notifications', icon:Bell },
    { to:'/criteria', label:'Criteria', icon:FileText },
  ] : [
    { to:'/', label:'Overview', icon:LayoutDashboard },
    { to:'/activities', label:'Department activities', icon:BookOpen },
    { to:'/reviews', label:'Appraisal reviews', icon:ShieldCheck },
    { to:'/notifications', label:'Notifications', icon:Bell },
  ]
  links.push({ to:'/profile', label:'My profile', icon:UserRound })
  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark"><GraduationCap size={22}/></div><div><b>FacultyAdvance</b><span>Academic growth platform</span></div></div>
      <div className="workspace-label">WORKSPACE</div>
      <nav>{links.map(item => <Link key={item.to} to={item.to} className={`nav-link ${location.pathname===item.to?'active':''}`}><item.icon size={18}/>{item.label}</Link>)}</nav>
      <div className="sidebar-bottom"><div className="mini-profile"><div className="avatar">{(user.first_name || user.username).slice(0,1).toUpperCase()}</div><div className="profile-text"><b>{user.first_name} {user.last_name}</b><span>{roleLabel[user.role]}</span></div><button className="icon-button" onClick={logout} title="Sign out"><LogOut size={17}/></button></div></div>
    </aside>
    <main className="main-area"><header className="topbar"><div><span className="eyebrow">UNIVERSITY FACULTY PORTAL</span><h1>{links.find(x=>x.to===location.pathname)?.label || 'FacultyAdvance'}</h1></div><div className="topbar-right"><span className="role-pill">{roleLabel[user.role]}</span><div className="avatar small">{(user.first_name || user.username).slice(0,1).toUpperCase()}</div></div></header>
      <div className="page-content"><Routes>
        <Route path="/" element={<Dashboard user={user}/>} />
        <Route path="/activities" element={<Activities user={user}/>} />
        <Route path="/research" element={<Research user={user}/>} />
        <Route path="/appraisal" element={<Appraisal user={user}/>} />
        <Route path="/reviews" element={isReviewer ? <Reviews user={user}/> : <Navigate to="/" replace />} />
        <Route path="/notifications" element={<NotificationsPage />} />
        <Route path="/profile" element={<Profile user={user} onUpdated={setUser} />} />
        <Route path="/criteria" element={user.role === 'ADMIN' ? <CriteriaManagement /> : <Navigate to="/" replace />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes></div>
    </main>
  </div>
}

function Login({ onLogin }) {
  const [username,setUsername]=useState(''); const [password,setPassword]=useState(''); const [error,setError]=useState(''); const [busy,setBusy]=useState(false)
  const submit=async e=>{e.preventDefault();setError('');setBusy(true);try{await onLogin(username,password)}catch(error){setError(error.response?.data?.detail||'Unable to sign in. Check your username and password.')}finally{setBusy(false)}}
  return <div className="auth-layout"><div className="auth-showcase"><div className="brand light"><div className="brand-mark"><GraduationCap size={22}/></div><b>FacultyAdvance</b></div><div className="showcase-copy"><span className="eyebrow light-text">A SMARTER WAY TO GROW</span><h1>Every achievement.<br/>One academic profile.</h1><p>Bring teaching, research and institutional contributions together in one transparent appraisal workspace.</p><div className="showcase-stats"><div><b>01</b><span>Unified record</span></div><div><b>02</b><span>Evidence-led review</span></div><div><b>03</b><span>Career progression</span></div></div></div><div className="showcase-footer">Faculty appraisal · Research discovery · Digital reporting</div></div><div className="auth-form-wrap"><form className="auth-card" onSubmit={submit}><span className="eyebrow">WELCOME BACK</span><h2>Sign in to your account</h2><p className="muted">Use your university faculty portal credentials.</p>{error&&<div className="alert error" role="alert">{error}</div>}<label>Username<input value={username} onChange={e=>setUsername(e.target.value)} autoComplete="username" required placeholder="Enter username"/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required placeholder="Enter password"/></label><button className="primary-btn full" disabled={busy}>{busy?'Signing in…':'Sign in'}<ChevronRight size={17}/></button><a className="secondary-btn full" href={`${api.defaults.baseURL}auth/google/start/`}>Continue with Google Workspace</a><p className="hint">Available to existing accounts in your configured Workspace domain.</p><p className="auth-switch"><Link to="/reset-password">Forgot password?</Link></p><p className="auth-switch">Need an account? <Link to="/register">Faculty registration</Link></p><p className="auth-switch"><Link to="/resend-verification">Resend email verification</Link></p>{import.meta.env.DEV&&<div className="demo-note"><b>Local demo accounts</b><span>Faculty: faculty / Faculty@12345</span><span>HOD: hod / Hod@12345</span><span>Admin: universityadmin / Admin@12345</span></div>}</form></div></div>
}

function GoogleSSOCallback({onLogin}) {
 const navigate=useNavigate();const [error,setError]=useState('');const [busy,setBusy]=useState(true);const started=useRef(false)
 useEffect(()=>{if(started.current)return;started.current=true;const ticket=new URLSearchParams(window.location.search).get('ticket');window.history.replaceState({},document.title,window.location.pathname);if(!ticket){setError('Google sign-in ticket is missing. Start again.');setBusy(false);return}api.post('auth/google/complete/',{ticket}).then(({data})=>{localStorage.setItem('access_token',data.access);localStorage.setItem('refresh_token',data.refresh);onLogin(data.user);navigate('/',{replace:true})}).catch(e=>setError(e.response?.data?.detail||'Google sign-in failed. Start again.')).finally(()=>setBusy(false))},[navigate,onLogin])
 return <div className="auth-layout"><div className="auth-showcase"><div className="brand light"><div className="brand-mark"><GraduationCap size={22}/></div><b>FacultyAdvance</b></div><div className="showcase-copy"><span className="eyebrow light-text">GOOGLE WORKSPACE SIGN-IN</span><h1>Completing<br/>your sign-in.</h1></div></div><div className="auth-form-wrap"><div className="auth-card"><h2>{busy?'Please wait?':'Sign-in status'}</h2>{error&&<div className="alert error" role="alert">{error}</div>}{error&&<p className="auth-switch"><Link to="/login">Return to sign in</Link></p>}</div></div></div>
}

function Register(){
 const [form,setForm]=useState({username:'',email:'',first_name:'',last_name:'',employee_code:'',department:'',designation:'',password:''});const [msg,setMsg]=useState('');const [err,setErr]=useState('')
 const change=e=>setForm({...form,[e.target.name]:e.target.value})
 const submit=async e=>{e.preventDefault();setMsg('');setErr('');try{const {data}=await api.post('auth/register/',form);setMsg(data.detail||'Account created. Check your email to verify the address before signing in.')}catch(e){setErr(e.response?.data?.detail||JSON.stringify(e.response?.data||'Registration failed.'))}}
 return <div className="auth-layout"><div className="auth-showcase"><div className="brand light"><div className="brand-mark"><GraduationCap size={22}/></div><b>FacultyAdvance</b></div><div className="showcase-copy"><span className="eyebrow light-text">JOIN YOUR UNIVERSITY WORKSPACE</span><h1>Your academic journey,<br/>beautifully organized.</h1><p>Create your faculty account to maintain your academic contributions and appraisal history.</p></div><div className="showcase-footer">Faculty appraisal · Research discovery · Digital reporting</div></div><div className="auth-form-wrap"><form className="auth-card" onSubmit={submit}><span className="eyebrow">FACULTY REGISTRATION</span><h2>Create your account</h2><p className="muted">New registrations are assigned the Faculty role and must verify email before signing in.</p>{msg&&<div className="alert success">{msg}</div>}{err&&<div className="alert error">{err}</div>}<div className="form-grid"><label>First name<input name="first_name" value={form.first_name} onChange={change} required/></label><label>Last name<input name="last_name" value={form.last_name} onChange={change} required/></label></div><label>Username<input name="username" value={form.username} onChange={change} required/></label><label>Official email<input name="email" type="email" value={form.email} onChange={change} required/></label><div className="form-grid"><label>Employee code<input name="employee_code" value={form.employee_code} onChange={change} required/></label><label>Department<input name="department" value={form.department} onChange={change} required/></label></div><label>Designation<input name="designation" value={form.designation} onChange={change}/></label><label>Password (12+ characters, three character types)<input name="password" type="password" value={form.password} onChange={change} minLength="12" autoComplete="new-password" required/></label><button className="primary-btn full">Create account <ChevronRight size={17}/></button><p className="auth-switch">Already registered? <Link to="/login">Sign in</Link></p></form></div></div>
}

function PasswordRecovery(){
 const location=useLocation();const params=new URLSearchParams(location.search);const uid=params.get('uid');const token=params.get('token');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [message,setMessage]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false)
 const submit=async e=>{e.preventDefault();setBusy(true);setError('');setMessage('');try{if(uid&&token){const {data}=await api.post('auth/password-reset/confirm/',{uid,token,new_password:password});setMessage(data.detail)}else{const {data}=await api.post('auth/password-reset/',{email});setMessage(data.detail)}}catch(e){setError(e.response?.data?.detail||'Unable to process this request.')}finally{setBusy(false)}}
 return <div className="auth-layout"><div className="auth-showcase"><div className="brand light"><div className="brand-mark"><GraduationCap size={22}/></div><b>FacultyAdvance</b></div><div className="showcase-copy"><span className="eyebrow light-text">ACCOUNT RECOVERY</span><h1>Secure access<br/>to your profile.</h1><p>Reset your password using a time-limited link sent to your verified email address.</p></div></div><div className="auth-form-wrap"><form className="auth-card" onSubmit={submit}><span className="eyebrow">PASSWORD RESET</span><h2>{uid&&token?'Choose a new password':'Request reset link'}</h2><p className="muted">Reset links are time limited and can only be used once.</p>{message&&<div className="alert success" role="status">{message}</div>}{error&&<div className="alert error" role="alert">{error}</div>}{uid&&token?<label>New password (12+ characters)<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength="12" autoComplete="new-password" required/></label>:<label>Verified account email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></label>}<button className="primary-btn full" disabled={busy}>{busy?'Please wait…':uid&&token?'Update password':'Send reset link'}</button><p className="auth-switch"><Link to="/login">Back to sign in</Link></p></form></div></div>
}

function VerifyEmailPage(){
 const location=useLocation();const token=new URLSearchParams(location.search).get('token');const [message,setMessage]=useState('Verifying your email…');const [error,setError]=useState('')
 useEffect(()=>{if(!token){setMessage('');setError('Verification link is missing. Request a new email verification link.');return}api.post('auth/verify-email/',{token}).then(r=>setMessage(r.data.detail)).catch(e=>{setMessage('');setError(e.response?.data?.detail||'Verification link is invalid or expired.')})},[token])
 return <div className="auth-layout"><div className="auth-showcase"><div className="brand light"><div className="brand-mark"><GraduationCap size={22}/></div><b>FacultyAdvance</b></div><div className="showcase-copy"><span className="eyebrow light-text">EMAIL VERIFICATION</span><h1>Confirm your<br/>email address.</h1></div></div><div className="auth-form-wrap"><div className="auth-card"><h2>Email verification</h2>{message&&<div className="alert success" role="status">{message}</div>}{error&&<div className="alert error" role="alert">{error}</div>}<p className="auth-switch"><Link to="/login">Continue to sign in</Link> · <Link to="/resend-verification">Request a new link</Link></p></div></div></div>
}

function ResendVerificationPage(){
 const [email,setEmail]=useState('');const [message,setMessage]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false)
 const submit=async e=>{e.preventDefault();setBusy(true);setError('');setMessage('');try{const {data}=await api.post('auth/resend-verification/',{email});setMessage(data.detail)}catch(e){setError(e.response?.data?.detail||'Unable to send a verification link.')}finally{setBusy(false)}}
 return <div className="auth-layout"><div className="auth-showcase"><div className="brand light"><div className="brand-mark"><GraduationCap size={22}/></div><b>FacultyAdvance</b></div><div className="showcase-copy"><span className="eyebrow light-text">EMAIL VERIFICATION</span><h1>Verify your<br/>account email.</h1></div></div><div className="auth-form-wrap"><form className="auth-card" onSubmit={submit}><h2>Resend verification</h2><p className="muted">If your account needs verification, we'll send a new time-limited link.</p>{message&&<div className="alert success" role="status">{message}</div>}{error&&<div className="alert error" role="alert">{error}</div>}<label>Account email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="email" required/></label><button className="primary-btn full" disabled={busy}>{busy?'Sending…':'Send verification email'}</button><p className="auth-switch"><Link to="/login">Back to sign in</Link></p></form></div></div>
}

function PageIntro({title,description,action}){return <div className="page-intro"><div><h2>{title}</h2><p>{description}</p></div>{action}</div>}
function StatCard({label,value,caption,icon:Icon,tone='blue'}){return <div className="stat-card"><div className={`stat-icon ${tone}`}><Icon size={19}/></div><div><span>{label}</span><strong>{value ?? '—'}</strong><small>{caption}</small></div></div>}
function Dashboard({user}){
 const [data,setData]=useState(null);const [error,setError]=useState('')
 useEffect(()=>{
   Promise.all([
     api.get('dashboard/'),
     api.get('notifications/')
   ]).then(([dashboardRes, notificationsRes]) => {
     const notifications = notificationsRes.data.results || notificationsRes.data || []
     setData({ ...dashboardRes.data, unreadNotifications: notifications.filter(item => !item.is_read).length })
   }).catch(()=>setError('Could not load dashboard data.'))
 },[])
 const faculty=user.role==='FACULTY'
 return <><div className="welcome-banner"><div><span className="eyebrow light-text">YOUR ACADEMIC WORKSPACE</span><h2>Good to see you, {user.first_name || user.username}.</h2><p>{faculty?'Keep your academic contributions current and your appraisal ready.':'Review faculty contributions and keep the appraisal process moving.'}</p></div><div className="banner-art"><GraduationCap size={62}/></div></div>{error&&<div className="alert error">{error}</div>}{!data?<div className="loading-card">Loading dashboard…</div>:<><div className="stats-grid">{faculty?<><StatCard label="Activities recorded" value={data.activity_count} caption={`${data.verified_activities} verified`} icon={ActivityIcon}/><StatCard label="Publications" value={data.publication_count} caption="Research records" icon={BookOpen} tone="purple"/><StatCard label="Projects" value={data.project_count} caption="Academic projects" icon={BriefcaseBusiness} tone="orange"/><StatCard label="Indicative score" value={moneyOrScore(data.score?.total_score)} caption="Verified contributions only" icon={ChartNoAxesCombined} tone="green"/></>:<><StatCard label="Faculty members" value={data.faculty_count} caption="In your access scope" icon={GraduationCap}/><StatCard label="Submissions" value={data.submission_count} caption="Total appraisal records" icon={ClipboardList} tone="purple"/><StatCard label="Pending review" value={data.pending_count} caption="Awaiting a final decision" icon={ActivityIcon} tone="orange"/><StatCard label="Unread notifications" value={data.unreadNotifications} caption="Action items" icon={Bell} tone="green"/></>}</div><div className="content-grid"><section className="panel"><div className="panel-heading"><div><h3>{faculty?'Appraisal snapshot':'Review workflow'}</h3><p>{faculty?'A quick look at your current appraisal status.':'Submission status across your department or university.'}</p></div><ClipboardList size={20}/></div>{faculty?<><div className="status-row"><span>Latest submission</span><StatusBadge status={data.latest_submission?.status}/></div><div className="status-row"><span>Appraisal score</span><b>{moneyOrScore(data.score?.total_score)} points</b></div><div className="status-row"><span>Activities awaiting verification</span><b>{Math.max(0, data.activity_count-data.verified_activities)}</b></div><Link className="text-link" to="/appraisal">Open my appraisal <ChevronRight size={15}/></Link></>:<><div className="status-row"><span>All submissions</span><b>{data.submission_count}</b></div><div className="status-row"><span>Pending / in progress</span><b>{data.pending_count}</b></div><div className="status-row"><span>Approved</span><b>{data.approved_count}</b></div><Link className="text-link" to="/reviews">Open appraisal reviews <ChevronRight size={15}/></Link></>}</section><section className="panel info-panel"><div className="info-icon"><ShieldCheck size={22}/></div><h3>{faculty?'Keep your evidence up to date':'Evidence-led evaluation'}</h3><p>{faculty?'Attach a certificate, DOI or supporting document to each activity. Reviewers can only include verified activities in your appraisal score.':'Verify the evidence attached to faculty activity records before finalizing an appraisal decision.'}</p><Link to={faculty?'/activities':'/reviews'} className="secondary-btn">{faculty?'Manage activities':'Review submissions'} <ChevronRight size={16}/></Link></section></div></>}</>
}

function NotificationsPage(){
  const [items,setItems]=useState([]);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState('');const [error,setError]=useState('')
  const load=async()=>{setLoading(true);setError('');try{const res=await api.get('notifications/');setItems(res.data.results||res.data||[])}catch{setError('Unable to load notifications. Please try again.')}finally{setLoading(false)}}
  useEffect(()=>{load()},[])
  const markRead=async id=>{setBusy(String(id));setError('');try{await api.post(`notifications/${id}/mark_read/`);setItems(current=>current.map(item=>item.id===id?{...item,is_read:true}:item))}catch{setError('Could not update this notification. Please try again.')}finally{setBusy('')}}
  const markAllRead=async()=>{setBusy('all');setError('');try{await api.post('notifications/mark_all_read/');setItems(current=>current.map(item=>({...item,is_read:true})))}catch{setError('Could not mark notifications as read. Please try again.')}finally{setBusy('')}}
  const unreadCount=items.filter(item=>!item.is_read).length
  return <><PageIntro title="Notifications" description="Keep track of appraisal updates, verification decisions and review actions." action={<div className="inline-actions"><button className="secondary-btn" onClick={load} disabled={loading||Boolean(busy)}>Refresh</button>{unreadCount>0&&<button className="primary-btn" onClick={markAllRead} disabled={loading||Boolean(busy)}>{busy==='all'?'Updating…':`Mark all read (${unreadCount})`}</button>}</div>} />{error&&<div className="alert error" role="alert">{error}</div>}{loading?<div className="loading-card">Loading notifications…</div>:<div className="panel">{items.length===0?<EmptyState title="No notifications" description="You are all caught up for now."/>:<div className="notifications-list">{items.map(n=><div key={n.id} className={`notification-item ${n.is_read?'read':'unread'}`}><div><b>{n.message}</b><small>{fmtDate(n.created_at)}</small></div>{!n.is_read&&<button className="secondary-btn" onClick={()=>markRead(n.id)} disabled={Boolean(busy)}>{busy===String(n.id)?'Updating…':'Mark as read'}</button>}</div>)}</div>}</div>}</>
}

function Profile({user,onUpdated}){
  const [form,setForm]=useState({first_name:user.first_name||'',last_name:user.last_name||'',email:user.email||'',phone:user.phone||'',google_scholar_url:user.google_scholar_url||''})
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [success,setSuccess]=useState('')
  const change=e=>setForm(current=>({...current,[e.target.name]:e.target.value}))
  const submit=async e=>{e.preventDefault();setBusy(true);setError('');setSuccess('');try{const {data}=await api.patch('auth/me/',form);onUpdated(data);setSuccess('Profile details saved.')}catch(e){setError(e.response?.data?.detail||'Unable to save profile details.')}finally{setBusy(false)}}
  const exportData=async()=>{setError('');try{const {data}=await api.get('auth/me/export/');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='facultyadvance-personal-data.json';link.click();URL.revokeObjectURL(url)}catch{setError('Unable to export your data right now.')}}
  return <><PageIntro title="My profile" description="Update your contact details and review your institution-managed faculty information." action={<button className="secondary-btn" onClick={exportData}>Export my data</button>} />{error&&<div className="alert error" role="alert">{error}</div>}{success&&<div className="alert success" role="status">{success}</div>}<form className="panel activity-form" onSubmit={submit}><div className="panel-heading"><div><h3>Personal details</h3><p>Your name and contact details are used in appraisal reports and notifications.</p></div><UserRound size={20}/></div><div className="form-grid"><label>First name<input name="first_name" value={form.first_name} onChange={change} required maxLength="150"/></label><label>Last name<input name="last_name" value={form.last_name} onChange={change} required maxLength="150"/></label></div><label>Official email<input name="email" type="email" value={form.email} onChange={change} required maxLength="254"/></label><label>Phone<input name="phone" type="tel" value={form.phone} onChange={change} maxLength="20"/></label><label>Google Scholar profile URL (optional)<input name="google_scholar_url" type="url" value={form.google_scholar_url} onChange={change} placeholder="https://scholar.google.com/citations?user=YOUR_ID"/><small className="hint">Saved as a manual reconciliation reference; FacultyAdvance does not scrape this page.</small></label><div className="form-grid"><label>Employee code<input value={user.employee_code||'Not assigned'} readOnly/></label><label>Department<input value={user.department||'Not assigned'} readOnly/></label></div><label>Designation<input value={user.designation||'Not assigned'} readOnly/></label><div className="form-actions"><button className="primary-btn" disabled={busy}>{busy?'Saving…':'Save profile'}</button></div></form></>
}

function CriteriaManagement(){
  const [policies,setPolicies]=useState([]);const [periods,setPeriods]=useState([]);const [selected,setSelected]=useState(null);const [rulesText,setRulesText]=useState('{}');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('')
  const load=async()=>{setError('');try{const [policyResponse,periodResponse]=await Promise.all([api.get('policies/'),api.get('periods/')]);const policyItems=policyResponse.data.results||policyResponse.data||[];setPolicies(policyItems);setPeriods(periodResponse.data.results||periodResponse.data||[])}catch{setError('Unable to load appraisal policies.')}}
  useEffect(()=>{load()},[])
  const createDraft=async()=>{const period=periods.find(item=>item.is_active);if(!period){setError('Create or activate an appraisal period before drafting its policy.');return}const version=Math.max(0,...policies.filter(item=>item.period===period.id).map(item=>item.version))+1;setBusy(true);setError('');try{const {data}=await api.post('policies/',{period:period.id,version,rules:{}});setSelected(data);setRulesText(JSON.stringify(data.rules,null,2));setMessage('Draft created. Add policy rules and save before approval.');await load()}catch(e){setError(apiErrorMessage(e,'Unable to create policy draft.'))}finally{setBusy(false)}}
  const saveDraft=async()=>{if(!selected||selected.status!=='DRAFT')return;setBusy(true);setError('');try{const rules=JSON.parse(rulesText);const {data}=await api.patch(`policies/${selected.id}/`,{rules});setSelected(data);setMessage('Draft saved. Approval makes this policy immutable.');await load()}catch(e){setError(apiErrorMessage(e,'Rules must be valid JSON with non-negative points_per_item and optional max_points.'))}finally{setBusy(false)}}
  const approve=async()=>{if(!selected)return;setBusy(true);setError('');try{const {data}=await api.post(`policies/${selected.id}/approve/`);setSelected(data);setMessage('Policy approved and locked for this appraisal version.');await load()}catch(e){setError(apiErrorMessage(e,'Unable to approve policy.'))}finally{setBusy(false)}}
  const openPolicy=policy=>{setSelected(policy);setRulesText(JSON.stringify(policy.rules,null,2));setMessage('')}
  return <><PageIntro title="Appraisal policies" description="Create period-specific scoring drafts. Approved versions are immutable and recorded with each submission." action={<button className="primary-btn" onClick={createDraft} disabled={busy}><Plus size={16}/> New policy draft</button>} />{message&&<div className="alert success">{message}</div>}{error&&<div className="alert error" role="alert">{error}</div>}<div className="panel table-panel"><div className="table-toolbar"><div><h3>Policy versions</h3><p>Only approved policies contribute to appraisal scores.</p></div></div>{policies.length===0?<EmptyState title="No policies configured" description="Create and approve a scoring policy before faculty submit an appraisal."/>:<div className="table-wrap"><table><thead><tr><th>Period</th><th>Version</th><th>Status</th><th>Approved by</th><th>Action</th></tr></thead><tbody>{policies.map(policy=><tr key={policy.id}><td>{periods.find(item=>item.id===policy.period)?.name||`Period ${policy.period}`}</td><td>{policy.version}</td><td><StatusBadge status={policy.status}/></td><td>{policy.approved_by||'—'}</td><td><button className="secondary-btn" onClick={()=>openPolicy(policy)}>View / edit</button></td></tr>)}</tbody></table></div>}</div>{selected&&<div className="panel activity-form policy-editor"><div className="panel-heading"><div><h3>Period {selected.period} · Version {selected.version} · {selected.status}</h3><p>Rules are keyed by activity category; specify points_per_item and optionally max_points.</p></div></div><label>Policy rules (JSON)<textarea value={rulesText} onChange={e=>setRulesText(e.target.value)} rows="14" readOnly={selected.status!=='DRAFT'} spellCheck="false"/></label><div className="form-actions"><button className="secondary-btn" onClick={()=>setSelected(null)}>Close</button>{selected.status==='DRAFT'&&<><button className="secondary-btn" onClick={saveDraft} disabled={busy}>{busy?'Saving…':'Save draft'}</button><button className="primary-btn" onClick={approve} disabled={busy}>{busy?'Approving…':'Approve & lock'}</button></>}</div></div>}</>
}

function Activities({user}){
 const [items,setItems]=useState([]);const [show,setShow]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [success,setSuccess]=useState('');const [form,setForm]=useState({category:'PUBLICATION',title:'',description:'',activity_date:new Date().toISOString().slice(0,10),organizer:'',authors:'',journal_or_venue:'',doi:'',role_or_level:''});const [file,setFile]=useState(null)
 const load=()=>api.get('activities/').then(r=>setItems(r.data.results||r.data)).catch(()=>setError('Unable to load activities.'))
 useEffect(()=>{load()},[])
 const change=e=>setForm({...form,[e.target.name]:e.target.value})
 const submit=async e=>{e.preventDefault();if(file&&file.size>evidenceUploadMaxMb*1024*1024){setError(`Evidence file must be ${evidenceUploadMaxMb} MB or smaller.`);return}setBusy(true);setError('');setSuccess('');try{const {data}=await api.post('activities/',form);if(file){const fd=new FormData();fd.append('file',file);await api.post(`activities/${data.id}/evidence/`,fd,{headers:{'Content-Type':'multipart/form-data'}})}setSuccess('Activity saved. It is now pending verification.');setForm({...form,title:'',description:'',doi:'',authors:'',journal_or_venue:''});setFile(null);setShow(false);load()}catch(e){setError(JSON.stringify(e.response?.data||'Could not save activity.'))}finally{setBusy(false)}}
 const verify=async(id,verification_status)=>{try{await api.post(`activities/${id}/verify/`,{verification_status});load()}catch(e){setError('Could not update verification status.')}}
 return <><PageIntro title={user.role==='FACULTY'?'Academic activities':'Department activities'} description={user.role==='FACULTY'?'Maintain a complete record of your teaching, research and institutional contributions.':'Review academic activities submitted by faculty in your access scope.'} action={user.role==='FACULTY'?<button className="primary-btn" onClick={()=>setShow(!show)}><Plus size={17}/> Add activity</button>:null}/>{error&&<div className="alert error">{error}</div>}{success&&<div className="alert success">{success}</div>}{show&&<form className="panel activity-form" onSubmit={submit}><div className="panel-heading"><div><h3>Add an activity</h3><p>Enter the activity details and attach evidence, if available.</p></div><button className="icon-button" type="button" onClick={()=>setShow(false)}><X size={18}/></button></div><div className="form-grid"><label>Activity category<select name="category" value={form.category} onChange={change}>{categories.map(x=><option value={x[0]} key={x[0]}>{x[1]}</option>)}</select></label><label>Activity date<input type="date" name="activity_date" value={form.activity_date} onChange={change} required/></label></div><label>Title<input name="title" value={form.title} onChange={change} required placeholder="Enter activity or publication title"/></label><div className="form-grid"><label>Authors (optional)<input name="authors" value={form.authors} onChange={change}/></label><label>Journal / venue / organization<input name="journal_or_venue" value={form.journal_or_venue} onChange={change}/></label></div><div className="form-grid"><label>DOI (if applicable)<input name="doi" value={form.doi} onChange={change}/></label><label>Organizer / funding body<input name="organizer" value={form.organizer} onChange={change}/></label></div><label>Details<textarea name="description" value={form.description} onChange={change} rows="3"/></label><label>Supporting evidence (PDF/JPG/PNG, max {evidenceUploadMaxMb} MB)<input type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={e=>setFile(e.target.files[0]||null)}/></label><div className="form-actions"><button className="secondary-btn" type="button" onClick={()=>setShow(false)}>Cancel</button><button className="primary-btn" disabled={busy}>{busy?'Saving…':'Save activity'}</button></div></form>}
 <div className="panel table-panel"><div className="table-toolbar"><div><h3>Activity history</h3><p>{items.length} record(s) found</p></div><span className="hint">Only verified activities contribute to the score.</span></div>{items.length===0?<EmptyState title="No activities yet" description="Add your first research, teaching or academic activity."/>:<div className="table-wrap"><table><thead><tr><th>Activity</th><th>Category</th><th>Date</th><th>Evidence</th><th>Status</th>{user.role!=='FACULTY'&&<th>Review</th>}</tr></thead><tbody>{items.map(a=><tr key={a.id}><td><b>{a.title}</b><small>{a.doi||a.journal_or_venue||a.faculty_name||''}</small></td><td>{a.category_label}</td><td>{fmtDate(a.activity_date)}</td><td>{a.evidence?.length ? <EvidenceDownload evidence={a.evidence[0]} /> : '—'}</td><td><StatusBadge status={a.verification_status}/></td>{user.role!=='FACULTY'&&<td><div className="inline-actions"><button className="tiny-btn green" onClick={()=>verify(a.id,'VERIFIED')}>Verify</button><button className="tiny-btn red" onClick={()=>verify(a.id,'REJECTED')}>Reject</button></div></td>}</tr>)}</tbody></table></div>}</div></>
}

function Research({user}){
 const [query,setQuery]=useState('');const [results,setResults]=useState([]);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [message,setMessage]=useState('');const [importing,setImporting]=useState('')
 const [orcidQuery,setOrcidQuery]=useState('');const [orcidResults,setOrcidResults]=useState([]);const [orcidProfile,setOrcidProfile]=useState(null);const [orcidBusy,setOrcidBusy]=useState(false);const [orcidError,setOrcidError]=useState('')
 const search=async e=>{e.preventDefault();setBusy(true);setError('');setMessage('');try{const {data}=await api.get('research/crossref/',{params:{q:query}});setResults(data.results||[]);if(!data.results?.length)setMessage('No matching records found. Try another title or author.')}catch(e){setError(e.response?.data?.detail||'Publication search failed.')}finally{setBusy(false)}}
 const importDoi=async doi=>{setImporting(doi);setError('');try{await api.post('research/crossref/import/',{doi});setMessage('Publication imported to your activities as pending verification.');setResults(results.filter(r=>r.doi!==doi))}catch(e){setError(e.response?.data?.detail||'Could not import publication.')}finally{setImporting('')}}
 const searchOrcid=async e=>{e.preventDefault();setOrcidBusy(true);setOrcidError('');try{const {data}=await api.get('research/orcid/search/',{params:{q:orcidQuery}});setOrcidResults(data.results||[])}catch(e){setOrcidError(e.response?.data?.detail||'ORCID search failed.')}finally{setOrcidBusy(false)}}
 const linkOrcid=async id=>{setOrcidBusy(true);setOrcidError('');try{await api.patch('auth/me/',{orcid_id:id});const {data}=await api.get('research/orcid/profile/',{params:{orcid_id:id}});setOrcidProfile(data);setMessage('ORCID identifier saved to your profile. Publications still need manual confirmation and evidence.')}catch(e){setOrcidError(apiErrorMessage(e,'Could not save or look up this ORCID profile.'))}finally{setOrcidBusy(false)}}
 return <><PageIntro title="Publication finder" description="Discover scholarly records through Crossref and link a public ORCID researcher profile."/>{user?.google_scholar_url&&<div className="notice-card"><BookOpen size={19}/><div><b>Google Scholar manual reference</b><p>Use your saved public profile to reconcile works manually; FacultyAdvance does not read it.</p><a href={user.google_scholar_url} target="_blank" rel="noreferrer">Open your Google Scholar profile</a></div></div>}<div className="panel search-panel"><form className="search-form" onSubmit={search}><div className="search-input"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search by paper title, author or keyword…" required/></div><button className="primary-btn" disabled={busy}>{busy?'Searching…':'Search Crossref'}</button></form><p className="hint">Crossref results are suggestions, not proof of authorship. Confirm each record and attach institutional evidence.</p></div>{error&&<div className="alert error">{error}</div>}{message&&<div className="alert success">{message}</div>}{results.length>0&&<div className="research-results">{results.map((r,i)=><div className="panel research-card" key={r.doi||i}><div className="research-type">CROSSREF RESULT</div><h3>{r.title||'Untitled record'}</h3><p>{r.authors||'Author information not listed'}</p><div className="research-meta"><span>{r.venue||'Venue not listed'}</span><span>DOI: {r.doi||'Not available'}</span></div><button className="secondary-btn" disabled={!r.doi||importing===r.doi} onClick={()=>importDoi(r.doi)}>{importing===r.doi?'Importing…':'Import to my activities'} <ChevronRight size={15}/></button></div>)}</div>}<div className="panel search-panel"><h3>Link your ORCID profile</h3><p className="hint">Search the public ORCID registry, then confirm the matching researcher. This links the identifier to your account; it does not import works or prove authorship.</p><form className="search-form" onSubmit={searchOrcid}><div className="search-input"><Search size={18}/><input value={orcidQuery} onChange={e=>setOrcidQuery(e.target.value)} placeholder="Search ORCID by name or identifier" required/></div><button className="primary-btn" disabled={orcidBusy}>{orcidBusy?'Searching…':'Search ORCID'}</button></form>{orcidError&&<div className="alert error" role="alert">{orcidError}</div>}{orcidProfile&&<div className="status-row"><b>{orcidProfile.display_name}</b><span>{orcidProfile.orcid_id}</span></div>}{orcidResults.map(item=><div className="status-row" key={item.orcid_id}><span>{item.display_name} · {item.orcid_id}</span><button className="secondary-btn" disabled={orcidBusy} onClick={()=>linkOrcid(item.orcid_id)}>Link profile</button></div>)}</div><div className="notice-card"><BookOpen size={19}/><div><b>Google Scholar records</b><p>This app does not scrape Google Scholar. Save your public profile URL in your profile settings, then use it as a manual reference while adding works through Crossref or the activity form. Attach evidence for each claim.</p></div></div></>
}

function Appraisal({user}){
 const [score,setScore]=useState(null);const [periods,setPeriods]=useState([]);const [subs,setSubs]=useState([]);const [statement,setStatement]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [success,setSuccess]=useState('')
 const load=()=>Promise.all([api.get('score/').then(r=>setScore(r.data)),api.get('periods/').then(r=>setPeriods(r.data.results||r.data)),api.get('submissions/').then(r=>setSubs(r.data.results||r.data))]).catch(()=>setError('Could not load appraisal information.'))
 useEffect(()=>{load()},[])
 const submit=async()=>{setBusy(true);setError('');setSuccess('');try{await api.post('submissions/submit/',{faculty_statement:statement});setSuccess('Your appraisal has been submitted for review.');load()}catch(e){setError(e.response?.data?.detail||'Submission failed.')}finally{setBusy(false)}}
 const download=async id=>{try{const r=await api.get(`submissions/${id}/pdf/`,{responseType:'blob'});const url=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=url;a.download=`faculty-appraisal-${id}.pdf`;a.click();URL.revokeObjectURL(url)}catch{setError('Could not download report.')}}
 return <><PageIntro title="My appraisal" description="Review your verified activity score, submit your annual appraisal and track review decisions."/>{error&&<div className="alert error">{error}</div>}{success&&<div className="alert success">{success}</div>}<div className="appraisal-summary"><div className="score-card"><span className="eyebrow light-text">CURRENT INDICATIVE SCORE</span><strong>{score?.policy?.configured?moneyOrScore(score.total_score):'—'}</strong><span>Points from verified activities</span><div className="score-foot">Final evaluation is subject to your institution's approved policy.</div></div><div className="panel score-breakdown"><div className="panel-heading"><div><h3>Score breakdown</h3><p>Only verified records are included.</p></div><ChartNoAxesCombined size={20}/></div>{score?.breakdown?.map(row=><div className="breakdown-row" key={row.category}><span>{row.label} <small>({row.verified_count} × {row.points_per_item})</small></span><b>{moneyOrScore(row.subtotal)}</b></div>)}</div></div>{score?.note&&<div className={`alert ${score.policy?.configured?'success':'error'} score-note`} role="status">{score.note}</div>}{user.role==='FACULTY'&&<div className="panel submit-panel"><div><h3>Submit appraisal</h3><p>Check that activities and supporting evidence are complete before submitting.</p><div className="period-info">Active appraisal period: <b>{periods.find(p=>p.is_active)?.name||'No active period configured'}</b></div></div><label>Faculty statement / summary<textarea rows="3" value={statement} onChange={e=>setStatement(e.target.value)} placeholder="Summarize your key contributions during this appraisal period…"/></label><button className="primary-btn" onClick={submit} disabled={busy||!periods.some(p=>p.is_active)||!score?.policy?.configured}>{busy?'Submitting…':'Submit for review'} <ChevronRight size={16}/></button></div>}<div className="panel table-panel"><div className="table-toolbar"><div><h3>Submission history</h3><p>Track your submitted appraisal reports.</p></div></div>{subs.length===0?<EmptyState title="No submissions yet" description="Your submitted appraisal forms will appear here."/>:<div className="table-wrap"><table><thead><tr><th>Appraisal period</th><th>Submitted</th><th>Score</th><th>Status</th><th>Report</th></tr></thead><tbody>{subs.map(s=><tr key={s.id}><td><b>{s.period_name}</b></td><td>{fmtDate(s.submitted_at)}</td><td>{moneyOrScore(s.total_score)}</td><td><StatusBadge status={s.status}/></td><td><button className="download-btn" onClick={()=>download(s.id)}><ArrowDownToLine size={15}/> PDF</button></td></tr>)}</tbody></table></div>}</div></>
}

function Reviews({user}){
 const [subs,setSubs]=useState([]);const [selected,setSelected]=useState(null);const [activities,setActivities]=useState([]);const [comments,setComments]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [sort,setSort]=useState('-submitted_at');const [search,setSearch]=useState('');const [page,setPage]=useState(1);const [pageInfo,setPageInfo]=useState({count:0,next:null,previous:null})
 const load=()=>api.get('submissions/',{params:{ordering:sort,search,page}}).then(r=>{setSubs(r.data.results||r.data);setPageInfo({count:r.data.count??r.data.length,next:r.data.next,previous:r.data.previous})}).catch(()=>setError('Could not load submissions.'))
 useEffect(()=>{load()},[sort,page])
 const open=async s=>{setSelected(s);setComments('');const r=await api.get('activities/',{params:{faculty:s.faculty}});setActivities(r.data.results||r.data)}
 const decision=async value=>{if(!selected)return;setBusy(true);setError('');try{await api.post(`submissions/${selected.id}/review/`,{decision:value,comments});setSelected(null);load()}catch(e){setError(e.response?.data?.detail||'Review could not be saved.')}finally{setBusy(false)}}
 const verify=async(id,value)=>{try{await api.post(`activities/${id}/verify/`,{verification_status:value});const r=await api.get('activities/',{params:{faculty:selected.faculty}});setActivities(r.data.results||r.data)}catch{setError('Could not update activity verification.')}}
 const download=async id=>{try{const r=await api.get(`submissions/${id}/pdf/`,{responseType:'blob'});const url=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=url;a.download=`appraisal-${id}.pdf`;a.click();URL.revokeObjectURL(url)}catch{setError('Could not download report.')}}
 return <><PageIntro title="Appraisal reviews" description="Review faculty submissions, verify activity evidence and record appraisal decisions."/><div className="review-tools"><div className="search-input"><Search size={17}/><input placeholder="Search faculty, employee code or department" value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==='Enter'&&(page===1?load():setPage(1))}/></div><select value={sort} onChange={e=>setSort(e.target.value)}><option value="-submitted_at">Newest submissions</option><option value="faculty__first_name">Faculty name A–Z</option><option value="faculty__employee_code">Employee code</option><option value="total_score">Score (low to high)</option></select><button className="secondary-btn" onClick={()=>page===1?load():setPage(1)}>Apply</button></div>{error&&<div className="alert error">{error}</div>}<div className="panel table-panel"><div className="table-wrap"><table><thead><tr><th>Faculty member</th><th>Department</th><th>Period</th><th>Submitted</th><th>Score</th><th>Status</th><th>Actions</th></tr></thead><tbody>{subs.map(s=><tr key={s.id}><td><b>{s.faculty_name}</b><small>{s.employee_code||'No employee code'}</small></td><td>{s.department}</td><td>{s.period_name}</td><td>{fmtDate(s.submitted_at)}</td><td>{moneyOrScore(s.total_score)}</td><td><StatusBadge status={s.status}/></td><td><div className="inline-actions"><button className="tiny-btn" onClick={()=>open(s)}>Review</button><button className="download-btn" onClick={()=>download(s.id)}><ArrowDownToLine size={14}/></button></div></td></tr>)}</tbody></table>{subs.length===0&&<EmptyState title="No appraisal submissions" description="Faculty submissions will appear here once they are submitted."/>}</div><div className="table-toolbar"><span className="hint">{pageInfo.count} submissions ? page {page}</span><div className="inline-actions"><button className="secondary-btn" disabled={!pageInfo.previous} onClick={()=>setPage(p=>Math.max(1,p-1))}>Previous</button><button className="secondary-btn" disabled={!pageInfo.next} onClick={()=>setPage(p=>p+1)}>Next</button></div></div></div>{selected&&<div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setSelected(null)}><div className="review-modal"><div className="modal-heading"><div><span className="eyebrow">APPRAISAL REVIEW</span><h2>{selected.faculty_name}</h2><p>{selected.employee_code} · {selected.department} · {selected.period_name}</p></div><button className="icon-button" onClick={()=>setSelected(null)}><X size={19}/></button></div><div className="modal-body"><div className="status-row"><span>Current status</span><StatusBadge status={selected.status}/></div><div className="status-row"><span>Indicative verified score</span><b>{moneyOrScore(selected.total_score)} points</b></div><h3>Activities and evidence</h3>{activities.length===0?<p className="muted">No linked activity records were found.</p>:activities.map(a=><div className="review-activity" key={a.id}><div><b>{a.title}</b><span>{a.category_label} · {fmtDate(a.activity_date)}</span><small>{a.doi||a.journal_or_venue}</small>{a.evidence?.[0]&&<EvidenceDownload evidence={a.evidence[0]} />}</div><StatusBadge status={a.verification_status}/><div className="inline-actions"><button className="tiny-btn green" onClick={()=>verify(a.id,'VERIFIED')}>Verify</button><button className="tiny-btn red" onClick={()=>verify(a.id,'REJECTED')}>Reject</button></div></div>)}<label>Reviewer comments<textarea value={comments} onChange={e=>setComments(e.target.value)} rows="3" placeholder="Add feedback or explain the decision…"/></label></div><div className="modal-actions"><button className="secondary-btn" onClick={()=>decision('UNDER_REVIEW')} disabled={busy}>Mark under review</button><button className="secondary-btn" onClick={()=>decision('REVISION')} disabled={busy}>Request revision</button><button className="danger-btn" onClick={()=>decision('REJECTED')} disabled={busy}>Reject</button><button className="primary-btn" onClick={()=>decision('APPROVED')} disabled={busy}>Approve appraisal</button></div></div></div>}</>
}

function StatusBadge({status}){const map={VERIFIED:['Verified','good'],APPROVED:['Approved','good'],PENDING:['Pending','warn'],SUBMITTED:['Submitted','info'],UNDER_REVIEW:['Under review','warn'],REVISION:['Revision requested','orange'],REJECTED:['Rejected','bad']};const [label,cls]=map[status]||[status||'Not submitted','neutral'];return <span className={`status-badge ${cls}`}>{label}</span>}
function EvidenceDownload({evidence}){
 const [busy,setBusy]=useState(false);const [error,setError]=useState('')
 const download=async()=>{setBusy(true);setError('');try{const {data}=await api.get(`evidence/${evidence.id}/download/`,{responseType:'blob'});const url=URL.createObjectURL(data);const link=document.createElement('a');link.href=url;link.download=evidence.original_name||'evidence';link.click();URL.revokeObjectURL(url)}catch{setError('Download unavailable')}finally{setBusy(false)}}
 return <span><button type="button" className="secondary-btn" onClick={download} disabled={busy}>{busy?'Loading…':'View evidence'}</button>{error&&<small role="alert">{error}</small>}</span>
}
function EmptyState({title,description}){return <div className="empty-state"><div className="empty-icon"><FileText size={22}/></div><b>{title}</b><p>{description}</p></div>}

export default App
